mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string",
      "description": "Unique order identifier, for example ORD-1001.",
      "minLength": 1
    }
  },
  "required": ["orderId"],
  "additionalProperties": false
}

ee:message.ee:set-payload:
%dw 2.0
output application/java
var template = readUrl("classpath://mock-order-details.json", "application/json")
---
template update {
    case .orderId          -> vars.orderId
    case .orderReference   -> vars.orderId
    case .order_id         -> vars.orderId
    case .orderCode        -> vars.orderId
    case .externalOrderRef -> "EXT-REF-" ++ vars.orderId
    case .merchantOrderId  -> "MCH-" ++ vars.orderId ++ "-2026"
    case .platformOrderId  -> "PLT-" ++ vars.orderId
    case meta at .'_metadata' -> meta update {
        case .'_requestedOrderId' -> vars.orderId
    }
}
